{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
        {
            "@type": "Question",
            "name": "How much does a kitchen remodel cost in the Seattle area?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Kitchen remodeling typically ranges from about $15,000 for a cosmetic update to $75,000 or more for a full custom renovation. The cost depends on scope, materials, cabinetry style, countertops, appliances, and whether layout changes require plumbing or electrical work. Big Build Construction provides free, fixed-price written estimates."
            }
        },
        {
            "@type": "Question",
            "name": "How much does a bathroom remodel cost?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Bathroom remodels generally range from about $10,000 for a cosmetic refresh to $50,000 or more for a full luxury master bathroom, depending on tile, fixtures, glass, and whether plumbing changes are needed."
            }
        },
        {
            "@type": "Question",
            "name": "How long does a kitchen or bathroom remodel take?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Most kitchen remodels take 4 to 8 weeks and most bathroom remodels take 3 to 6 weeks. Cosmetic updates can be completed faster, while full gut renovations take longer."
            }
        },
        {
            "@type": "Question",
            "name": "What areas does Big Build Construction serve?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Big Build Construction serves Kent, Renton, Auburn, Federal Way, Tukwila, Covington, Maple Valley, Des Moines, Burien, SeaTac, Bellevue, Issaquah, Sammamish, Newcastle, and Seattle in King County, plus Pacific, Puyallup, Bonney Lake, and Tacoma in Pierce County."
            }
        },
        {
            "@type": "Question",
            "name": "Is Big Build Construction licensed and insured?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Yes. Big Build Construction is a licensed, bonded, and insured general contractor in Washington State."
            }
        },
        {
            "@type": "Question",
            "name": "Does Big Build Construction offer free estimates?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Yes. Big Build Construction offers free, no-obligation, fixed-price written estimates. Call (206) 356-5380 or request one through the website."
            }
        },
        {
            "@type": "Question",
            "name": "Do you do tub-to-shower conversions?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Yes. Tub-to-shower conversions are one of our most popular services, including plumbing modifications, waterproofing, tile installation, frameless glass, and barrier-free curbless shower options."
            }
        }
    ]
}

